                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<R and 0<=nx<C and g[ny][nx] and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                out.append((min(ys),min(xs),max(ys)-min(ys)+1,max(xs)-min(xs)+1,len(cells)))
    return out
