def transform(grid):
    g=[r[:] for r in grid]; R,C=len(g),len(g[0]); seen=set(); blocks=[]
    for i in range(R):
        for j in range(C):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=set()
                while st:
                    y,x=st.pop(); cells.add((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<R and 0<=nx<C and g[ny][nx] and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                blocks.append(cells)
    n9s=[sum(1 for y,x in c if g[y][x]==9) for c in blocks]
    m=min(n9s)
    for c,n9 in zip(blocks,n9s):
        if n9==m:
            for y,x in c: g[y][x]=0
    return g
